using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

// Register the OpenAI-backed chat client via MEAI abstraction
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .Use(new OpenAI.OpenAIClient(apiKey)
        .GetChatClient(modelId).AsIChatClient()));

builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

// Resolve services
var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

// Build the agent with tools
var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a research agent. Given a topic, use the web_search tool to find " +
    "relevant information, take notes with the take_note tool, then provide a " +
    "concise summary of your findings. Search multiple times if needed to gather " +
    "comprehensive information.");

// Prompt the user for a topic
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

// Run the agent
var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
    Tools = [AIFunctionFactory.Create(tools.WebSearch), AIFunctionFactory.Create(tools.TakeNote)],
    ModelOptions = new ChatOptions { Temperature = 0f, MaxOutputTokens = 2048 },
};

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n--- Research Notes ---");
foreach (var note in tools.Notes)
{
    Console.WriteLine($"• {note}");
}

// --- Tool Definitions ---

public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;

    [Description("Search the web for information on a query. Returns search result snippets.")]
    public string WebSearch([Description("The search query")] string query)
    {
        // Simulated web search results for demonstration.
        // Replace with a real search API (Bing, Google, etc.) in production.
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");
        return $"""
            Search results for "{query}":
            1. Wikipedia summary: {query} is a widely discussed topic with many facets including history, current developments, and future implications.
            2. Recent news: Several recent articles discuss new breakthroughs and ongoing debates related to {query}.
            3. Academic paper: A 2025 survey paper covers the state of the art in {query}, highlighting key challenges and opportunities.
            """;
    }

    [Description("Save a research note for later reference in the summary.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  [Tool] Note saved: \"{note[..Math.Min(note.Length, 60)]}...\"");
        return "Note saved successfully.";
    }
}

