using System.ComponentModel;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(pipeline => pipeline
    .UseFunctionInvocation()
    .Use(new OpenAI.OpenAIClient(apiKey)
        .GetChatClient(modelId).AsIChatClient()));

builder.Services.AddSingleton<ResearchTools>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = host.Services.GetRequiredService<ResearchTools>();

// Build the agent with tools registered in the constructor
var agent = new ChatClientAgent(
    chatClient,
    instructions: "You are a research agent. Given a topic, use the web_search tool to find " +
        "relevant information, take notes with the take_note tool to record key findings, " +
        "then provide a concise summary. Search multiple queries to get comprehensive coverage.",
    name: "ResearchAgent",
    tools: [AIFunctionFactory.Create(tools.WebSearch), AIFunctionFactory.Create(tools.TakeNote)]);

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var session = await agent.CreateSessionAsync("research-session");

var runOptions = new ChatClientAgentRunOptions
